/* eslint-disable max-len */
/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { SafeUrl, DomSanitizer } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';

@Component({
  selector: 'app-atmospheric-pressure',
  templateUrl: './atmospheric-pressure.component.html',
  styleUrls: ['./atmospheric-pressure.component.scss'],
})
export class AtmosphericPressurePage implements OnInit {

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  tunerPlusVideo: string | SafeUrl = 'InJWP';

  form: FormGroup;
  form2: FormGroup;

  pi = 3.14159265;
  p = 12.57;
  cr = 10.86;
  h = 1300;
  hb = 0;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.isShow = false;
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(25).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n === courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {

    this.tunerPlusVideo = G.TunerPlusTu5Video;

    this.form = this.fb.group({
      p_sea: [14.7, [Validators.required, Validators.min(1), Validators.max(100000)]],
      h: [1300, [Validators.required, Validators.min(-100000), Validators.max(100000)]],
      c: [15, [Validators.required, Validators.min(-1000), Validators.max(1000)]]
    });

    this.form2 = this.fb.group({
      p_sea: [14.7, [Validators.required, Validators.min(1), Validators.max(100000)]],
      p: [12.57, [Validators.required, Validators.min(-100000), Validators.max(100000)]],
      c: [15, [Validators.required, Validators.min(-1000), Validators.max(1000)]]
    });
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.p = +(((this.form.value.p_sea / 0.0001450377) * Math.pow(1 + ((-0.0065 / (this.form.value.c + 273.15)) * (this.form.value.h - this.hb)), 5.255876113278518)) * 0.0001450377).toFixed(2);
          // this.p = +(-9E-27 * Math.pow(this.form.value.h, 6) - 3E-22 * Math.pow(this.form.value.h, 5) + 4E-17 * Math.pow(this.form.value.h, 4) - 2E-12 * Math.pow(this.form.value.h, 3) + 8E-08 * Math.pow(this.form.value.h, 2) - 0.0017 * this.form.value.h + 14.696).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );

  }

  onCalc2() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.h = +(this.hb + ((this.form2.value.c + 273.15) / -0.0065) * (Math.pow((((this.form2.value.p / 0.0001450377) / (this.form2.value.p_sea / 0.0001450377))), 0.1902632365084836) - 1)).toFixed(1);
          // this.h = +(0.0145 * Math.pow(this.form2.value.p, 6) - 0.9129 * Math.pow(this.form2.value.p, 5) + 22.946 * Math.pow(this.form2.value.p, 4) - 294.87 * Math.pow(this.form2.value.p, 3) + 2083.6 * Math.pow(this.form2.value.p, 2) - 8869.1 * this.form2.value.p + 25622).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onReset() {

    this.p = 12.57;

    this.form.setValue({
      p_sea: 14.7,
      h: 1300,
      c: 15
    });
  }

  onReset2() {

    this.h = 1300;

    this.form2.setValue({
      p_sea: 14.7,
      p: 12.57,
      c: 15
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'bore':
        this.presentActiveAlertConfirm('قطر سیلندر یا پیستون بر حسب میلیمتر');
        break;
      case 'strok':
        this.presentActiveAlertConfirm('کورس پیستون برحسب میلیمتر');
        break;
      case 'bore_gasket':
        this.presentActiveAlertConfirm('قطر واشر سرسیلندر (قطر حفره ی سیلندر و پیستون) بر حسب میلیمتر');
        break;
      case 'strok_gasket':
        this.presentActiveAlertConfirm('ضخامت واشر سرسیلندر برحسب میلیمتر');
        break;
      case 'h_v':
        this.presentActiveAlertConfirm('حجم فرو رفتگی یا همان گودی محفظه ی احتراق سرسیلندر برحسب سانتیمتر مکعب (cc)');
        break;
      case 'p_v':
        this.presentActiveAlertConfirm('حجم فرو رفتگی یا برآمدگی سر پیستون برحسب سانتیمتر مکعب (cc). دقت شود که پیستون برآمده باشد باید عدد منفی وارد شود');
        break;
      case 'n':
        this.presentActiveAlertConfirm('تعداد سیلندر');
        break;
      case 'cubic':
        this.presentActiveAlertConfirm('حجم موتوری که محاسبه کرده اید بر حسب سانتیمتر مکعب');
        break;
      case 'rpm':
        this.presentActiveAlertConfirm('دور موتور مد نظر شما');
        break;
      case 'd':
        this.presentActiveAlertConfirm('دوریشن میل سوپاپ برحسب درجه');
        break;
      case 'r':
        this.presentActiveAlertConfirm('قطر رانر محاسبه شده برحسب سانتیمتر');
        break;
      case 'p_sea':
        this.presentActiveAlertConfirm('فشار هوا در سطح دریا برحسب پی اس آی (PSI)');
        break;
      case 'h':
        this.presentActiveAlertConfirm('ارتفاع از سطح دریا برحسب متر');
        break;
      case 'c':
        this.presentActiveAlertConfirm('دمای هوای محیط برحسب درجه سانتیگراد');
        break;
      case 'p':
        this.presentActiveAlertConfirm('فشار هوای محیط برحسب پی اس ای (PSI)');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
